#include "cdx/operations.h"

void cdx_tool_list(cdx_json_output *output) {
    static const char *const tools[] = {
        "{\"name\":\"tool_info\",\"title\":\"查看 Cordonix 状态\",\"description\":\"Cordonix version, platform and per-session document load/commit counters.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"execute_program\",\"title\":\"执行本地程序\",\"description\":\"Run an absolute native executable with literal argv, cwd and timeout. Uses owned Windows Job or Linux process-group cleanup. No shell expansion. External programs read disk, so explicitly commit memory edits first.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"program\",\"args\",\"cwd\"],\"properties\":{\"program\":{\"type\":\"string\"},\"args\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":512},\"cwd\":{\"type\":\"string\"},\"timeout_ms\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1800000},\"expected_exit_codes\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"}},\"stdin\":{\"type\":\"string\"},\"output_encoding\":{\"type\":\"string\",\"enum\":[\"utf-8\",\"cp936\",\"gbk\"]},\"output_limit_bytes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":262144}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}}",
        "{\"name\":\"workspace_open\",\"title\":\"打开文件（指定编码）\",\"description\":\"Load one source file into memory. Returns document_id, disk/memory SHA256, explicit encoding and EOL. AUTO accepts BOM/strict UTF8 only; choose cp936 for legacy files.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"enum\":[\"auto\",\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"list_directory\",\"title\":\"列出目录项\",\"description\":\"List immediate children of an existing absolute filesystem path, without recursion or shell expansion. include_hidden=true includes Windows hidden/system entries or POSIX dotfiles. max_entries defaults 200 (1..1000); extra visible entries set truncated=true. Returns names, types, file sizes and flags; order is unspecified. Does not read file contents.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\"},\"include_hidden\":{\"type\":\"boolean\",\"default\":false},\"max_entries\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"default\":200}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"resolve_path\",\"title\":\"解析已存在的路径\",\"description\":\"Normalize an absolute literal filesystem path (dot segments and separators) and verify that its directory entry exists. Returns path and type; not_found is distinct from an empty directory. Preserves link names, does not expand to a physical target, and does not support non-filesystem providers or wildcard patterns.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\"}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"verify_encoding\",\"title\":\"验证文件编码\",\"description\":\"Read-only batch check of fresh disk bytes: strict decoding, no text NUL, and byte-exact encoding round-trip. Requires an explicit encoding; a conflicting BOM returns encoding_mismatch (utf-8 permits a UTF-8 BOM). Preflight all 1..32 path entries and optional expected_count/allowed_root before file reads. allowed_root is lexical containment, not a symlink sandbox. Reports each result and preserves NOT_RUN after cancellation/timeout. Default 10s, checks between file operations; file I/O is not forcibly preempted. No content output, edits or workspace slots.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"paths\",\"encoding\"],\"properties\":{\"paths\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"minItems\":1,\"maxItems\":32},\"encoding\":{\"type\":\"string\",\"enum\":[\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]},\"expected_count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":32},\"allowed_root\":{\"type\":\"string\",\"minLength\":1},\"timeout_ms\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":60000,\"default\":10000}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"read_file\",\"title\":\"读取磁盘文件\",\"description\":\"Read a fresh disk snapshot in one call by absolute path and explicit encoding. Choose start_line/line_count, tail_lines (last N lines), or raw=true (whole decoded text); do not mix modes. max_bytes defaults 32768, maximum 262144. Tail/raw return output_limit without text if the complete result exceeds the budget. No persistent document or write. AUTO accepts BOM/strict UTF-8 only; select cp936 for GBK.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"enum\":[\"auto\",\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]},\"start_line\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":25165825,\"default\":1},\"line_count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"default\":200},\"max_bytes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":262144,\"default\":32768},\"tail_lines\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000},\"raw\":{\"type\":\"boolean\",\"default\":false}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"workspace_read\",\"title\":\"读取内存文档\",\"description\":\"Read the current memory revision without reloading disk. Default offset/limit uses UTF-8 bytes. Otherwise choose start_line/line_count, tail_lines, or raw=true with max_bytes (default 32768, max 262144); do not mix with byte fields. Preserves EOL. Tail/raw require the complete result to fit and return output_limit without text otherwise.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"offset\":{\"type\":\"integer\",\"minimum\":0},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":32768},\"start_line\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":25165825,\"default\":1},\"line_count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"default\":200},\"max_bytes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":262144,\"default\":32768},\"tail_lines\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000},\"raw\":{\"type\":\"boolean\",\"default\":false}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"workspace_edit\",\"title\":\"编辑文本（仅内存）\",\"description\":\"Exact memory-only replacement with expected current SHA and occurrence count. dry_run defaults true; false updates memory only. No encoding loss, fuzzy matches or disk writes.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"expected_sha256\",\"old\",\"new\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"expected_sha256\":{\"type\":\"string\"},\"old\":{\"type\":\"string\",\"minLength\":1},\"new\":{\"type\":\"string\"},\"expected_count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":10000},\"dry_run\":{\"type\":\"boolean\",\"default\":true}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false}}",
        "{\"name\":\"workspace_commit\",\"title\":\"提交文件到磁盘\",\"description\":\"Commit dirty memory to the source file after rereading disk identity and SHA. Conflict leaves disk unchanged. Preserves original encoding, BOM and EOL. One-file atomic replacement.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}}",
        "{\"name\":\"workspace_convert_encoding\",\"title\":\"转换文件编码（仅内存）\",\"description\":\"Lossless encoding conversion in memory, preserving Unicode text and line endings. Requires current SHA; dry_run defaults true. UTF8/UTF16/CP936; unrepresentable text is rejected. Commit separately.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"expected_sha256\",\"encoding\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"expected_sha256\":{\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"enum\":[\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]},\"dry_run\":{\"type\":\"boolean\",\"default\":true}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false}}",
        "{\"name\":\"workspace_status\",\"title\":\"查看文件修改状态\",\"description\":\"Memory/disk revision and dirty status; no disk reload. Commit always validates external disk changes.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"workspace_search\",\"title\":\"搜索内存文档\",\"description\":\"Search a literal UTF8 string in the memory revision, up to 100 match offsets. Returns no_match distinctly.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"pattern\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"pattern\":{\"type\":\"string\",\"minLength\":1}}},\"annotations\":{\"readOnlyHint\":true}}",
        "{\"name\":\"workspace_close\",\"title\":\"关闭内存文档\",\"description\":\"Release one document. Dirty memory requires explicit discard=true or a successful commit first. Session termination discards memory, never implicitly commits.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"discard\":{\"type\":\"boolean\",\"default\":false}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}}"
    };
    size_t i;
    cdx_json_raw(output, "{\"tools\":[");
    for (i = 0; i < sizeof(tools) / sizeof(tools[0]); ++i) {
        if (i) cdx_json_raw(output, ",");
        cdx_json_raw(output, tools[i]);
    }
    cdx_json_raw(output, "]}");
}
